def max_candles(A, Y, X):
    if A < Y:
        return A * X + 1
    else:
        return Y * X

# Read the number of test cases
T = int(input().strip())

# Process each test case
results = [max_candles(int(input().strip().split()[0]), int(input().strip().split()[1]), int(input().strip().split()[2])) for _ in range(T)]

# Print the results
for result in results:
    print(result)
